build/commit.go.patch:
--- a/build/commit.go
+++ b/build/commit.go
@@ -6,6 +6,7 @@ import (
 	"fmt"
 	"os"
 	"path/filepath"
+	"slices"
 	"strings"

 	"github.com/KogenAI/kogen-coordinator/git"
@@ -124,10 +125,35 @@ func (b *Attempt) commitApproved(ctx context.Context, ap Approved, restart bool)
 	if removalFailure != nil {
 		b.s.Puts(fmt.Sprintf("  note: could not remove the approval file %s: %s", approvalPath, removalFailure))
 	}
+	b.putReviewRepaired(pass.Tree)
 	b.putSpend()
 	return false, nil
 }

+// maxRepairedPaths is how many changed paths the review repaired line names.
+const maxRepairedPaths = 5
+
+// putReviewRepaired names the paths the review changed: those that differ between the tree the
+// review started on and the committed tree. It prints nothing when the review changed nothing
+// or its start tree is not recorded.
+func (b *Attempt) putReviewRepaired(committed string) {
+	if b.ReviewStart == "" || b.ReviewStart == committed {
+		return
+	}
+	paths, err := b.repo.Changed(b.ReviewStart, committed)
+	if err != nil || len(paths) == 0 {
+		return
+	}
+	slices.Sort(paths)
+	line := "  review repaired: "
+	if len(paths) > maxRepairedPaths {
+		line += strings.Join(paths[:maxRepairedPaths], ", ") + fmt.Sprintf(", and %d more", len(paths)-maxRepairedPaths)
+	} else {
+		line += strings.Join(paths, ", ")
+	}
+	b.s.Puts(line)
+}
+
 // putSpend writes what the Build spent: the repairs line, then the executor lines. The
 // repairs line leaves out a native token total of exactly "0" when an executor line follows,
 // since that total does not count the executor's own usage.

